SELECT a.id, a.alert_id, a.alert_title, a.alert_content, a.alert_source, a.source_object_id, a.rule_id, a.risk_level, a.matched_keywords, a.evidence_json, a.alert_status, a.handle_opinion, a.handler_user_id, a.handle_time, a.deleted, a.create_user_id, a.update_user_id, a.create_time, a.update_time FROM campus_alert a LEFT JOIN campus_monitor_result r ON a.alert_source = 'monitor' AND a.source_object_id = r.monitor_result_id AND r.deleted = 0 WHERE a.deleted = 0 AND a.alert_source = 'monitor'
AND r.monitor_task_id = #{monitorTaskId}
AND (a.alert_title LIKE CONCAT('%', #{keyword}, '%') OR a.alert_content LIKE CONCAT('%', #{keyword}, '%') OR a.matched_keywords LIKE CONCAT('%', #{keyword}, '%'))
AND a.risk_level = #{riskLevel}
AND a.alert_status = #{alertStatus}
ORDER BY a.id DESC

